// Pixel Runner – simple endless runner
// Canvas must exist with id="game"

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  // basic dimensions
  canvas.width = 800;
  canvas.height = 200;

  const GRAVITY = 0.6;
  const JUMP_VELOCITY = -12;
  const PLAYER_SIZE = 20; // 2‑pixel‑wide sprite scaled for visibility
  const GROUND_Y = canvas.height - PLAYER_SIZE;

  const player = {
    x: 50,
    y: GROUND_Y,
    vy: 0,
    width: PLAYER_SIZE,
    height: PLAYER_SIZE,
    onGround: true,
  };

  const obstacles = [];
  let spawnTimer = 0;
  const SPAWN_INTERVAL = 90; // frames
  let score = 0;
  let running = true;

  function spawnObstacle() {
    const size = PLAYER_SIZE * (Math.random() > 0.5 ? 1 : 2);
    obstacles.push({
      x: canvas.width,
      y: GROUND_Y + PLAYER_SIZE - size, // sit on ground (or gap note)
      width: size,
      height: size,
    });
  }

  function update() {
    // player physics
    player.vy += GRAVITY;
    player.y += player.vy;
    if (player.y >= GROUND_Y) {
      player.y = GROUND_Y;
      player.vy = 0;
      player.onGround = true;
    }

    // obstacles move left
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= 6; // speed
      // remove off‑screen
      if (o.x + o.width < 0) {
        obstacles.splice(i, 1);
        score++;
      }
    }

    // spawn logic
    spawnTimer++;
    if (spawnTimer >= SPAWN_INTERVAL) {
      spawnTimer = 0;
      spawnObstacle();
    }

    // collision detection
    for (const o of obstacles) {
      if (
        player.x < o.x + o.width &&
        player.x + player.width > o.x &&
        player.y < o.y + o.height &&
        player.y + player.height > o.y
      ) {
        running = false;
        break;
      }
    }
  }

  function draw() {
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // player (bright pixel)
    ctx.fillStyle = '#0f0';
    ctx.fillRect(player.x, player.y, player.width, player.height);

    // obstacles (red)
    ctx.fillStyle = '#f00';
    for (const o of obstacles) {
      ctx.fillRect(o.x, o.y, o.width, o.height);
    }

    // score
    ctx.fillStyle = '#fff';
    ctx.font = '16px monospace';
    ctx.fillText('Score: ' + score, 10, 20);
  }

  function loop() {
    if (!running) {
      ctx.fillStyle = '#fff';
      ctx.font = '24px monospace';
      ctx.fillText('Game Over – Score: ' + score, canvas.width / 2 - 120, canvas.height / 2);
      return;
    }
    update();
    draw();
    requestAnimationFrame(loop);
  }

  // input handling
  function jump() {
    if (player.onGround) {
      player.vy = JUMP_VELOCITY;
      player.onGround = false;
    }
  }
  document.addEventListener('keydown', (e) => {
    if (e.code === 'Space') jump();
  });
  canvas.addEventListener('mousedown', jump);
  canvas.addEventListener('touchstart', (e) => { e.preventDefault(); jump(); });

  // start
  loop();
})();
